function scheduleInfo(p){let pr=progress(p),deadline=dateOnly(p.deadline),start=dateOnly((p.startDate||p.createdAt||new Date().toISOString()).slice(0,10));if(!deadline)return{dText:'마감 미정',days:null,timePct:0,status:'보통',cls:'normal',gap:0};let now=new Date(),day=86400000,days=Math.ceil((deadline-now)/day),dText=days>0?'D-'+days:days===0?'D-DAY':'D+'+Math.abs(days),total=Math.max(day,deadline-start),elapsed=Math.max(0,Math.min(total,now-start)),timePct=Math.min(100,elapsed/total*100),gap=pr-timePct,status='보통',cls='normal';if(pr>=100){status='완료';cls='relaxed'}else if(days<0){status='마감 초과';cls='overdue'}else if(days<=2||gap<-20){status='긴급';cls='urgent'}else if(days<=7||gap<-8){status='주의';cls='urgent'}else if(gap>=12){status='여유';cls='relaxed'}return{dText,days,timePct,status,cls,gap}}

