function projectDeadline(p){return (p.deadline||'').slice(0,10)||'미정'}
function lastActivity(p){let stamps=[p.createdAt||'',...(p.sessions||[]).map(x=>x.savedAt||''),(p.runningSince?new Date(p.runningSince).toISOString():'')].filter(Boolean);return stamps.length?Math.max(...stamps.map(x=>new Date(x).getTime()||0)):0}
function sortedProjects(mode){let arr=[...data.projects],dateVal=v=>v&&v!=='미정'?new Date(v+'T12:00:00').getTime():Infinity;return arr.sort((a,b)=>{let sa=scheduleInfo(a),sb=scheduleInfo(b);if(mode==='deadline')return dateVal(projectDeadline(a))-dateVal(projectDeadline(b))||a.name.localeCompare(b.name,'ko');if(mode==='start')return dateVal(projectStart(a))-dateVal(projectStart(b))||a.name.localeCompare(b.name,'ko');if(mode==='recent')return lastActivity(b)-lastActivity(a)||a.name.localeCompare(b.name,'ko');if(mode==='progress')return progress(b)-progress(a)||dateVal(projectDeadline(a))-dateVal(projectDeadline(b));if(mode==='name')return a.name.localeCompare(b.name,'ko');let rank=x=>x.status==='마감 초과'?0:x.status==='긴급'?1:x.status==='주의'?2:x.status==='보통'?3:x.status==='여유'?4:x.status==='완료'?5:6;return rank(sa)-rank(sb)||(sa.days??Infinity)-(sb.days??Infinity)||dateVal(projectDeadline(a))-dateVal(projectDeadline(b))})}

function utcDay(v){let m=String(v||'').slice(0,10).match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?Date.UTC(+m[1],+m[2]-1,+m[3]):null}
function importedRange(p,x){let start=(p.startDate||x.savedAt||p.createdAt||new Date().toISOString()).slice(0,10),end=(x.importedUntil||p.importedUntil||new Date().toISOString()).slice(0,10);if(utcDay(end)<utcDay(start))end=start;return{start,end}}
function importedMonthShare(p,x,key){let r=importedRange(p,x),start=utcDay(r.start),end=utcDay(r.end),monthStart=utcDay(key+'-01'),d=new Date(monthStart),monthEnd=Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0),overlap=Math.max(0,Math.min(end,monthEnd)-Math.max(start,monthStart)+86400000),total=Math.max(86400000,end-start+86400000);return overlap/total}
function importedDayShare(p,x,date){let r=importedRange(p,x),start=utcDay(r.start),end=utcDay(r.end),day=utcDay(date);if(day<start||day>end)return 0;let days=Math.max(1,Math.round((end-start)/86400000)+1);return 1/days}
function monthsInRange(start,end){let out=[],d=new Date(utcDay(start)),last=utcDay(end);while(d.getTime()<=last){out.push(d.toISOString().slice(0,7));d=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,1))}return out}
function monthStats(key){let totalMs=0,totalEarned=0,projects=[];data.projects.forEach(p=>{let rate=expectedRate(p),cum=0,pm=0,pe=0,ss=[...(p.sessions||[])].sort((a,b)=>Number(!!b.imported)-Number(!!a.imported)||new Date(a.savedAt)-new Date(b.savedAt));ss.forEach(x=>{let dur=Math.max(0,x.durationMs||0),before=Math.min(p.budget,cum*rate/3600000);cum+=dur;let inc=Math.max(0,Math.min(p.budget,cum*rate/3600000)-before);if(x.imported){let share=importedMonthShare(p,x,key);pm+=dur*share;pe+=inc*share}else if(monthKey(x.savedAt)===key){pm+=dur;pe+=inc}});let unsaved=Math.max(0,sessionLive(p));if(unsaved&&key===new Date().toISOString().slice(0,7)){let before=Math.min(p.budget,cum*rate/3600000);let inc=Math.max(0,Math.min(p.budget,(cum+unsaved)*rate/3600000)-before);pm+=unsaved;pe+=inc}if(pm||pe)projects.push({p,ms:pm,earned:pe});totalMs+=pm;totalEarned+=pe});return{totalMs,totalEarned,projects}}
function availableMonths(){let set=new Set([new Date().toISOString().slice(0,7)]);data.projects.forEach(p=>(p.sessions||[]).forEach(x=>{if(x.imported){let r=importedRange(p,x);monthsInRange(r.start,r.end).forEach(k=>set.add(k))}else set.add(monthKey(x.savedAt))}));return [...set].sort().reverse()}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const project=id=>data.projects.find(p=>p.id===id),sessionLive=p=>(p.sessionMs||0)+(p.runningSince?Date.now()-p.runningSince:0),live=p=>(p.elapsedMs||0)+sessionLive(p),expectedRate=p=>p.budget/p.hours,earned=p=>Math.min(p.budget,live(p)*expectedRate(p)/3600000),actualRate=p=>live(p)>=60000?earned(p)/(live(p)/3600000):null,over=p=>Math.max(0,(live(p)/(p.hours*3600000)-1)*100),progress=p=>Math.min(100,live(p)/(p.hours*3600000)*100),isToday=v=>new Date(v).toDateString()===new Date().toDateString(),todayWorked=p=>(p.sessions||[]).filter(x=>!x.imported&&isToday(x.savedAt)).reduce((a,x)=>a+(x.durationMs||0),0)+sessionLive(p);
function dateKey(v){return (v||'').slice(0,10)}
function workedOnDate(p,date){let total=(p.sessions||[]).reduce((a,x)=>a+(x.imported?(x.durationMs||0)*importedDayShare(p,x,date):(dateKey(x.savedAt)===date?(x.durationMs||0):0)),0);if(date===new Date().toISOString().slice(0,10))total+=sessionLive(p);return total}
function totalWorkedOnDate(date){return data.projects.reduce((a,p)=>a+workedOnDate(p,date),0)}
function earnedOnDate(p,date){let rate=expectedRate(p),cum=0,total=0,ss=[...(p.sessions||[])].sort((a,b)=>Number(!!b.imported)-Number(!!a.imported)||new Date(a.savedAt)-new Date(b.savedAt));ss.forEach(x=>{let dur=Math.max(0,x.durationMs||0),before=Math.min(p.budget,cum*rate/3600000);cum+=dur;let inc=Math.max(0,Math.min(p.budget,cum*rate/3600000)-before);if(x.imported)total+=inc*importedDayShare(p,x,date);else if(dateKey(x.savedAt)===date)total+=inc});let today=new Date().toISOString().slice(0,10),unsaved=date===today?Math.max(0,sessionLive(p)):0;if(unsaved){let before=Math.min(p.budget,cum*rate/3600000);total+=Math.max(0,Math.min(p.budget,(cum+unsaved)*rate/3600000)-before)}return total}
