// ---- 다음 원본 스크립트 블록 ----


(function(){
  function mountMainMascot(){
    const stage=document.querySelector('.pixel-stage');
    if(!stage || typeof levelMascotSVG!=='function') return;
    const totalMs=(data?.projects||[]).reduce((sum,p)=>sum+(typeof live==='function'?live(p):0),0);
    const hours=totalMs/3600000;
    const tier=Math.max(0,Math.min(5,[0,50,150,300,600,1000].filter(h=>hours>=h).length-1));
    stage.innerHTML='<div class="main-level-mascot">'+levelMascotSVG(tier)+'</div>';
  }
  const originalRender=window.render;
  if(typeof originalRender==='function'){
    window.render=function(){const r=originalRender.apply(this,arguments);mountMainMascot();return r};
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',mountMainMascot);
  else mountMainMascot();
})();


// ---- 다음 원본 스크립트 블록 ----


(function(){
  function placeProfile(){
    const stage=document.querySelector('.pixel-stage');
    const summary=document.querySelector('.side-summary');
    const kicker=summary&&summary.querySelector('.profile-kicker');
    const nick=summary&&summary.querySelector('.nickname-row');
    const level=document.getElementById('sideLevel');
    if(!stage||!summary||!kicker||!nick||!level)return;
    let profile=document.querySelector('.hero-profile');
    if(!profile){
      profile=document.createElement('div');
      profile.className='hero-profile';
      stage.insertAdjacentElement('afterend',profile);
    }
    profile.append(kicker,nick,level);
  }
  const previous=window.render;
  if(typeof previous==='function'){
    window.render=function(){const result=previous.apply(this,arguments);placeProfile();return result};
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',placeProfile);else placeProfile();
})();


// ---- 다음 원본 스크립트 블록 ----


(()=>{
  const FOCUS_KEY='todaysant-focus-mode-v1';
  let focusOn=localStorage.getItem(FOCUS_KEY)==='1';
  const topbar=document.querySelector('.topbar');
  const status=document.getElementById('globalStatus');
  const actions=document.createElement('div');
  actions.className='topbar-actions';
  const focusBtn=document.createElement('button');
  focusBtn.type='button';
  focusBtn.id='focusModeBtn';
  focusBtn.className='focus-mode-btn';
  focusBtn.innerHTML='<span class="focus-btn-icon" aria-hidden="true">◆</span><span>집중 모드 시작</span>';
  if(status&&status.parentNode===topbar){
    topbar.insertBefore(actions,status);
    actions.append(focusBtn,status);
  }else if(topbar){ topbar.appendChild(focusBtn); }

  const overlay=document.getElementById('focusOverlay');
  const shell=document.getElementById('focusShell');
  const exitBtn=document.getElementById('focusExitBtn');

  function currentProject(){
    return typeof project==='function' ? project(selectedId||data.activeId) : null;
  }
  function mascotSrc(){
    const img=document.querySelector('.pixel-stage img');
    return img?.src||'';
  }
  function setFocus(on){
    focusOn=!!on;
    localStorage.setItem(FOCUS_KEY,focusOn?'1':'0');
    overlay.classList.toggle('show',focusOn);
    overlay.setAttribute('aria-hidden',focusOn?'false':'true');
    document.body.classList.toggle('focus-active',focusOn);
    if(focusOn) updateFocus();
  }
  function updateFocus(){
    if(!focusOn)return;
    const p=currentProject();
    if(!p){
      shell.innerHTML='<div class="focus-empty"><strong>선택된 프로젝트가 없어요.</strong><br>전체 보기로 돌아가 프로젝트를 선택해주세요.</div>';
      return;
    }
    const total=data.projects.reduce((sum,x)=>sum+live(x),0);
    const level=antLevel(total);
    const running=!!p.runningSince;
    shell.innerHTML=`
      <div class="focus-mascot"><img src="${mascotSrc()}" alt="디지털 개미 마스코트"></div>
      <div class="focus-level">LV.${level.lv} · ${esc(data.profile.nickname||level.title)}</div>
      <h1 class="focus-project"><span class="focus-project-emoji" aria-hidden="true">${esc(p.emoji||'🎬')}</span><span class="focus-project-name">${esc(p.name)}</span></h1>
      <div class="focus-status">${running?'⛏ 조용히 채굴 중':'채굴을 잠시 멈췄어요'}</div>
      <div class="focus-timer">${duration(sessionLive(p))}</div>
      <div class="focus-caption">현재 작업 세션</div>
      <div class="focus-earned">₩${won(todayEarned(p))}</div>
      <div class="focus-earned-label">오늘 번 시간값</div>
      <button class="focus-action ${running?'':'paused'}" id="focusToggleBtn" type="button">${running?'Ⅱ 잠시 멈춤':'▶ 시간값 캐기 시작'}</button>
      <div class="focus-note">누적 정보와 일정은 전체 보기에서 확인할 수 있어요.</div>`;
    const toggleBtn=document.getElementById('focusToggleBtn');
    if(toggleBtn)toggleBtn.onclick=()=>{toggle(p.id);setTimeout(updateFocus,0)};
  }
  focusBtn.onclick=()=>setFocus(true);
  exitBtn.onclick=()=>setFocus(false);
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&focusOn)setFocus(false)});
  setInterval(updateFocus,1000);
  setFocus(focusOn);
})();

// PWA install and offline support
let deferredPwaPrompt=null;
const pwaInstallBtn=document.getElementById('pwaInstallBtn');
window.addEventListener('beforeinstallprompt',event=>{
  event.preventDefault();
  deferredPwaPrompt=event;
  pwaInstallBtn?.classList.add('show');
});
pwaInstallBtn?.addEventListener('click',async()=>{
  if(!deferredPwaPrompt){
    toast?.('iPhone은 Safari 공유 버튼에서 홈 화면에 추가해 주세요.');
    return;
  }
  deferredPwaPrompt.prompt();
  await deferredPwaPrompt.userChoice;
  deferredPwaPrompt=null;
  pwaInstallBtn.classList.remove('show');
});
window.addEventListener('appinstalled',()=>{pwaInstallBtn?.classList.remove('show');toast?.('TodaysAnt가 설치됐어요.');});
if('serviceWorker' in navigator){
  window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(console.error));
}
